// src/Inscription.jsx
import React, { useState } from "react";
import { motion } from "framer-motion";
import { User, Building, Mail, Lock } from "lucide-react";
import Navbar from "./Navbar";
import Footer from "./Footer";


const InputField = ({
  icon: Icon,
  type = "text",
  placeholder,
  value,
  onChange,
  error,
  showPassword,
  togglePassword,
}) => (
  <div className="relative mb-4">
    <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
      <Icon className="h-5 w-5 text-gray-400" />
    </div>
    <input
      type={type === "password" && showPassword ? "text" : type}
      placeholder={placeholder}
      value={value}
      onChange={onChange}
      className={`w-full pl-10 pr-${type === "password" ? "12" : "4"} py-3 bg-gray-800 border ${
        error ? "border-red-500" : "border-gray-700"
      } rounded-xl text-white placeholder-gray-400 focus:outline-none focus:border-purple-500 focus:ring-2 focus:ring-purple-500/20 transition-all duration-300`}
    />
    {type === "password" && (
      <button
        type="button"
        onClick={togglePassword}
        className="absolute inset-y-0 right-0 pr-3 flex items-center"
      >
        {showPassword ? (
          <Lock className="h-5 w-5 text-gray-400 hover:text-purple-400 transition-colors" />
        ) : (
          <Lock className="h-5 w-5 text-gray-400 hover:text-purple-400 transition-colors" />
        )}
      </button>
    )}
    {error && (
      <motion.p
        initial={{ opacity: 0, y: -10 }}
        animate={{ opacity: 1, y: 0 }}
        className="text-red-400 text-sm mt-1 ml-1"
      >
        {error}
      </motion.p>
    )}
  </div>
);

const Button = ({ children, disabled = false, onClick }) => (
  <motion.button
    whileHover={
      !disabled
        ? { scale: 1.02, boxShadow: "0 0 20px rgba(139, 92, 246, 0.4)" }
        : {}
    }
    whileTap={!disabled ? { scale: 0.98 } : {}}
    disabled={disabled}
    onClick={onClick}
    className="w-full bg-gradient-to-r from-purple-600 to-indigo-600 hover:from-indigo-600 hover:to-purple-600 text-white font-semibold py-3 px-6 rounded-xl shadow-lg transition-all duration-300 disabled:opacity-50 disabled:cursor-not-allowed"
  >
    {children}
  </motion.button>
);
 
export default function Inscription() {
  
  const [formData, setFormData] = useState({
    prenom: "",
    nom: "",
    email: "",
    password: "",
    confirmPassword: "",
  });
  const [errors, setErrors] = useState({});
  const [showPassword, setShowPassword] = useState(false);
  const [showConfirmPassword, setShowConfirmPassword] = useState(false);
  const [isLoading, setIsLoading] = useState(false);

  const handleChange = (field) => (e) => {
    setFormData((prev) => ({ ...prev, [field]: e.target.value }));
    if (errors[field]) {
      setErrors((prev) => ({ ...prev, [field]: "" }));
    }
  };

  const validateForm = () => {
    const newErrors = {};
    if (!formData.prenom.trim()) newErrors.prenom = "Le prénom est requis";
    if (!formData.nom.trim()) newErrors.nom = "Le nom est requis";
   
    if (!formData.email.trim()) {
      newErrors.email = "L'email est requis";
    } else if (!/\S+@\S+\.\S+/.test(formData.email)) {
      newErrors.email = "Format d'email invalide";
    }
    if (!formData.password) {
      newErrors.password = "Le mot de passe est requis";
    } else if (formData.password.length < 8) {
      newErrors.password = "Le mot de passe doit contenir au moins 8 caractères";
    }
    if (!formData.confirmPassword) {
      newErrors.confirmPassword = "Confirmez votre mot de passe";
    } else if (formData.password !== formData.confirmPassword) {
      newErrors.confirmPassword = "Les mots de passe ne correspondent pas";
    }
    return newErrors;
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    const newErrors = validateForm();
    if (Object.keys(newErrors).length > 0) {
      setErrors(newErrors);
      return;
    }
    setIsLoading(true);
    setTimeout(() => {
      setIsLoading(false);
      alert("Inscription réussie !");
    }, 2000);
  };

  return (
    <>
      <Navbar />
    
      <div className="min-h-screen bg-gray-900 flex items-center justify-center px-4 sm:px-6 lg:px-8">
        <div className="fixed inset-0 bg-gradient-to-br from-gray-900 via-purple-900/10 to-indigo-900/10"></div>
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.6 }}
          className="relative max-w-md w-full space-y-8"
        >
          <div className="bg-gray-800/50 backdrop-blur-lg rounded-2xl shadow-2xl p-6  mt-40 mb-20 sm:p-8 border border-gray-700/50">
            <div className="text-center mb-8">
              <motion.h2
                initial={{ opacity: 0 }}
                animate={{ opacity: 1 }}
                transition={{ delay: 0.2 }}
                className="text-2xl sm:text-3xl font-bold bg-gradient-to-r from-purple-400 to-indigo-500 text-transparent bg-clip-text"
              >
                Créer un compte
              </motion.h2>
              <motion.p
                initial={{ opacity: 0 }}
                animate={{ opacity: 1 }}
                transition={{ delay: 0.4 }}
                className="mt-2 text-sm text-gray-400"
              >
                Rejoignez Veille Marchés dès aujourd'hui
              </motion.p>
            </div>

            <div className="space-y-4">
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                <InputField
                  icon={User}
                  placeholder="Prénom"
                  value={formData.prenom}
                  onChange={handleChange("prenom")}
                  error={errors.prenom}
                />
                <InputField
                  icon={User}
                  placeholder="Nom"
                  value={formData.nom}
                  onChange={handleChange("nom")}
                  error={errors.nom}
                />
              </div>

             

              <InputField
                icon={Mail}
                type="email"
                placeholder="Adresse email"
                value={formData.email}
                onChange={handleChange("email")}
                error={errors.email}
              />

              <InputField
                icon={Lock}
                type="password"
                placeholder="Mot de passe"
                value={formData.password}
                onChange={handleChange("password")}
                error={errors.password}
                showPassword={showPassword}
                togglePassword={() => setShowPassword(!showPassword)}
              />

              <InputField
                icon={Lock}
                type="password"
                placeholder="Confirmer le mot de passe"
                value={formData.confirmPassword}
                onChange={handleChange("confirmPassword")}
                error={errors.confirmPassword}
                showPassword={showConfirmPassword}
                togglePassword={() =>
                  setShowConfirmPassword(!showConfirmPassword)
                }
              />

              <div className="pt-4">
                <Button disabled={isLoading} onClick={handleSubmit}>
                  {isLoading ? "Création en cours..." : "Créer mon compte"}
                </Button>
              </div>
            </div>

            <div className="mt-6 text-center">
              <p className="text-sm text-gray-400">
                Déjà un compte ?{" "}
                <a
                  href="/connexion"
                  className="text-purple-400 hover:text-purple-300 font-medium transition-colors"
                >
                  Se connecter
                </a>
              </p>
            </div>

            <div className="mt-4 text-center">
              <p className="text-xs text-gray-500">
                En vous inscrivant, vous acceptez nos{" "}
                <a href="#" className="text-purple-400 hover:text-purple-300 transition-colors">
                  conditions d'utilisation
                </a>{" "}
                et notre{" "}
                <a href="#" className="text-purple-400 hover:text-purple-300 transition-colors">
                  politique de confidentialité
                </a>
              </p>
            </div>
          </div>
        </motion.div>
      </div>
      <Footer />
    </>
  );
}
